def verify(ctx):
    """验收 result.json 交付件：检查 delivered 字段是否严格等于 actual file bytes"""
    import json

    try:
        # 读取交付文件
        data_bytes = ctx.read("result")
        if data_bytes is None:
            return {
                "status": "fail",
                "checks": [{"name": "file_exists", "status": "fail", "reason": "result 文件不存在"}]
            }

        # 解析 JSON
        try:
            content = json.loads(data_bytes.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            return {
                "status": "fail",
                "checks": [{"name": "valid_json", "status": "fail", "reason": f"JSON 解析失败：{str(e)}"}]
            }

        # 检查 delivered 字段是否存在
        if "delivered" not in content:
            return {
                "status": "fail",
                "checks": [
                    {"name": "has_delivered_field", "status": "fail", "reason": "缺少 delivered 字段"}
                ]
            }

        # 检查 delivered 值是否严格等于 actual file bytes
        # 根据业务要求，delivered 字段值必须严格等于 "actual file bytes"
        if content["delivered"] != "actual file bytes":
            return {
                "status": "fail",
                "checks": [
                    {"name": "delivered_value", "status": "fail", "reason": f"delivered 字段值不正确，期望 'actual file bytes'，实际为 '{content['delivered']}'"}
                ]
            }

        return {
            "status": "pass",
            "checks": [
                {"name": "file_exists", "status": "pass"},
                {"name": "valid_json", "status": "pass"},
                {"name": "has_delivered_field", "status": "pass"},
                {"name": "delivered_value", "status": "pass"}
            ]
        }

    except Exception as e:
        return {
            "status": "fail",
            "checks": [{"name": "overall", "status": "fail", "reason": f"验收执行异常：{str(e)}"}]
        }
